function visual(kind,small=false){const labels={produkt:'Blatt und Papierkranich',plan:'Skizzenbuch und Stift',dialog:'Sprechblasen für Austausch und Klärung',bauen:'Bausteine als Anwendungsmodell',werkzeug:'Stift und Werkzeug für die Weiterentwicklung',idee:'Sprechblasen und Glühbirnen',blick:'Tablet und Lupe',karte:'Landkarte und Lupe'};return `<div class="screen-visual ${kind}${small?' compact':''}" role="img" aria-label="${labels[kind]||labels.plan}"></div>`}
function materialSteps(module){return state.materials.filter(m=>m.module===module).sort((a,b)=>a.id.localeCompare(b.id))}
function moduleView(id){const m=MODULES[id];if(!m)return start();const art=id.startsWith('pruefen-a')?'produkt':id.startsWith('pruefen-b')?'werkzeug':id.startsWith('pruefen-c')?'blick':id.startsWith('lernen')?'bauen':id==='selbstlernen'?'karte':'dialog';return `<div class="screen-heading">${visual(art)}<div><div class="eyebrow">${id.startsWith('pruefen')?'PRÜFEN · Sek I':id.startsWith('lernen')?'LERNEN':id==='selbstlernen'?'SELBSTLERNEN':'SCHULENTWICKLUNG'}</div><h1>${esc(m.title)}</h1><p>${esc(m.intro)}</p></div></div><div class="mode-note">Auf Papier oder hier in der App: Die Arbeitsimpulse bleiben gleich. Digitale Notizen sind freiwillig.</div><div class="work-layout"><div>${m.steps.map(s=>`<section class="work-section"><h2>${esc(s.title)}</h2><div class="original-text">${esc(s.body)}</div>${s.pdf?`<a class="source-link" href="${esc(s.pdf)}" target="_blank" rel="noopener">Originalseite ansehen / drucken</a>`:''}${area(id+'__'+s.id,s.note)}</section>`).join('')}${(m.prompts||[]).map((p,i)=>`<details><summary>${esc(p.title)}</summary><pre id="module-prompt-${i}">${esc(p.body)}</pre><button class="secondary" data-copy-element="module-prompt-${i}">Prompt kopieren</button></details>`).join('')}${materialSteps(id).map(s=>`<section class="work-section"><div class="eyebrow">Vom Coach erhalten</div><h2>${esc(s.title)}</h2><pre id="material-text-${s.id}">${esc(s.body)}</pre><button class="secondary" data-copy-element="material-text-${s.id}">Text kopieren</button><label for="material-note-${s.id}">Meine Gedanken / meine Antwort</label><textarea id="material-note-${s.id}" data-material-note="${s.id}" maxlength="20000">${esc(state.materialNotes[s.id]||'')}</textarea><div class="print-only">${esc(state.materialNotes[s.id]||'')}</div></section>`).join('')}${id.startsWith('lernen-')?materialImportBox():''}<div class="actions"><a class="button" href="#speicher">Persönlichen Stand sichern</a><button class="secondary" data-action="print-current">Diese Seite drucken</button>${id==='rueckmeldung'?'<button class="secondary" data-action="print-card">Nur meine Rückmeldekarte drucken</button>':''}</div><p class="saved-note">${storageText()}</p></div><aside><section><h3>Material zum Mitnehmen</h3>${m.resources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.label)}</a>`).join('')}</section><section><h3>Unterstützung</h3><a href="#coaches">Coaches finden</a><a href="#start">Anderen Horizont öffnen</a>${id==='pruefen-a'?'<a href="#pruefen-b">Weiter zu B · Gestalten</a>':''}${id==='zukunftsatelier'?'<a href="#logbuch">Zum Logbuch</a>':''}</section></aside></div>`}
function materialImportBox(){return `<section class="subtle"><h3>Das nächste Material</h3><p>Der Coach stellt dir die passende Materialdatei zum richtigen Zeitpunkt bereit. Du kannst sie hier öffnen oder auf Papier weiterarbeiten.</p><label>Materialdatei vom Coach auswählen<input id="material-import" type="file" accept=".json,application/json"></label><div id="material-preview"></div></section>`}
function notesView(){return `<h1>Meine Notizen</h1><p>Persönlicher Arbeitsstand · keine automatische Abgabe</p>${notesEntries().map(n=>`<section class="work-section"><h2>${esc(n.label)}</h2><div class="original-text">${esc(n.value)}</div></section>`).join('')||'<p>Noch keine Notizen.</p>'}<div class="actions"><button data-action="print-current">Notizen drucken</button><a href="#speicher">Zurück zum Arbeitsstand</a></div>`}
function cardPrint(){const names=['weiter','entwickeln','klaeren'];return `<article class="personal-card"><div class="eyebrow">KI HORIZONTE · SCHULENTWICKLUNG</div><h1>Gemeinsam weiterdenken</h1>${names.map((id,i)=>`<section><h2>${['WEITERMACHEN','ENTWICKELN','KLÄREN'][i]}</h2><p>${esc(state.fields['rueckmeldung__'+id]||'—')}</p></section>`).join('')}<p>Name / Kontakt (freiwillig): ${esc(state.fields.rueckmeldung__kontakt||'—')}</p><small>Abgabe freiwillig, auch ohne Namen.</small></article><div class="actions"><button data-action="print-current">Karte drucken</button><a href="#rueckmeldung">Zurück zur Bearbeitung</a></div>`}
